func TestParse(t *testing.T) {
	valid := []struct {
		in  string
		maj, min, pat uint64
		pre []string
		bld []string
	}{
		{"1.2.3", 1, 2, 3, nil, nil},
		{"v1.2.3", 1, 2, 3, nil, nil},
		{"V1.2.3", 1, 2, 3, nil, nil},
		{"0.0.0", 0, 0, 0, nil, nil},
		{"1.0.0-alpha", 1, 0, 0, []string{"alpha"}, nil},
		{"1.0.0-0", 1, 0, 0, []string{"0"}, nil},
		{"1.0.0-x.7.z.92", 1, 0, 0, []string{"x", "7", "z", "92"}, nil},
		{"1.0.0+build.5", 1, 0, 0, nil, []string{"build", "5"}},
		{"1.0.0-alpha+exp.sha.5114f85", 1, 0, 0, []string{"alpha"}, []string{"exp", "sha", "5114f85"}},
		{"1.0.0-alpha-a.b-c-d.1", 1, 0, 0, []string{"alpha-a", "b", "c", "d", "1"}, nil},
	}
	for _, tc := range valid {
		v, err := Parse(tc.in)
		if err != nil {
			t.Errorf("Parse(%q) error: %v", tc.in, err)
			continue
		}
		want := Version{tc.maj, tc.min, tc.pat, tc.pre, tc.bld}
		if !reflect.DeepEqual(v, want) {
			t.Errorf("Parse(%q) = %+v, want %+v", tc.in, v, want)
		}
	}
}

func TestParseInvalid(t *testing.T) {
	invalid := []string{
		"",
		"1.2",            // missing parts
		"1",              // missing parts
		"1.2.3.4",        // too many core parts
		"01.2.3",         // leading zero in major
		"1.02.3",         // leading zero in minor
		"1.2.03",         // leading zero in patch
		"1.0.0-01",       // leading zero in numeric pre-release id
		"1.0.0-alpha..1", // empty identifier
		"1.0.0-",         // empty pre-release section
		"1.0.0+",         // empty build section
		"1.0.0-al pha",   // space
		"1.0.0-α",        // non-ASCII character
		"1.0.0-alpha_b",  // underscore not allowed
		"1.0.0-alpha/b",  // slash not allowed
		"1.0.0 alpha",    // trailing garbage
		"-1.2.3",         // no version at all
		"v",              // just the prefix
		"1.0.0-αlpha",    // mixed non-ASCII
	}
	for _, in := range invalid {
		if _, err := Parse(in); err == nil {
			t.Errorf("Parse(%q) succeeded, want error", in)
		}
	}
}

func TestString(t *testing.T) {
	cases := map[string]string{
		"1.2.3":                "1.2.3",
		"v1.2.3":               "1.2.3",
		"1.0.0-alpha":          "1.0.0-alpha",
		"1.0.0-alpha+beta":     "1.0.0-alpha+beta",
		"1.0.0-x.7.z.92+build": "1.0.0-x.7.z.92+build",
	}
	for in, want := range cases {
		got := MustParse(in).String()
		if got != want {
			t.Errorf("MustParse(%q).String() = %q, want %q", in, got, want)
		}
	}
}

